var n=`1075-sinigang-na-hipon`;var a=`world-1075`;var t=`PH`;var s=`southeast-asia`;var o=4;var r=41;var g={en:`Sinigang na Hipon`,ua:`Сініганг із креветками`};var m={en:`Sinigang na Hipon is a dish from Philippines prepared with yellow onion, tomato, daikon, green beans. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Сініганг із креветками, страва кухні країни Філіппіни, яку готують із таких продуктів: жовта цибуля, помідор, дайкон, стручкова квасоля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 15 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 15 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:15,i:[[`shrimp-stock`,1100,`ml`],[`yellow-onion`,160,`g`],[`tomato`,260,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 14 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 14 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:14,i:[[`daikon`,200,`g`],[`green-beans`,200,`g`],[`okra`,130,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 7 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 7 хвилин до готовності й м’якості.`,t:[`poaching`],m:7,i:[[`shrimp`,650,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`tamarind-concentrate`,65,`g`],[`fish-sauce`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`spinach`,160,`g`]]}];var h={slug:n,id:a,country:`PH`,region:s,servings:4,minutes:41,title:g,text:m,steps:d};export{t as country,h as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,m as text,g as title};